18	package org.apache.inlong.sort.tests.utils;
19	
20	import java.io.IOException;
21	import java.nio.charset.StandardCharsets;
22	import java.nio.file.Files;
23	import java.nio.file.Path;
24	import java.nio.file.Paths;
25	import java.util.List;
26	import java.util.Map;
27	import java.util.function.Function;
28	import java.util.stream.Collectors;
29	
30	/**
31	 * A file placeholder replacement tool.
32	 */
33	public class PlaceholderResolver {
34	
35	    /**
36	     * Default placeholder prefix
37	     */
38	    public static final String DEFAULT_PLACEHOLDER_PREFIX = "${";
39	
40	    /**
41	     * Default placeholder suffix
42	     */
43	    public static final String DEFAULT_PLACEHOLDER_SUFFIX = "}";
44	
45	    /**
46	     * Default singleton resolver
47	     */
48	    private static PlaceholderResolver defaultResolver = new PlaceholderResolver();
49	
50	    /**
51	     * Placeholder prefix
52	     */
53	    private String placeholderPrefix = DEFAULT_PLACEHOLDER_PREFIX;
54	
55	    /**
56	     * Placeholder suffix
57	     */
58	    private String placeholderSuffix = DEFAULT_PLACEHOLDER_SUFFIX;
59	
60	    private PlaceholderResolver() {
61	
62	    }
63	
64	    private PlaceholderResolver(String placeholderPrefix, String placeholderSuffix) {
65	        this.placeholderPrefix = placeholderPrefix;
66	        this.placeholderSuffix = placeholderSuffix;
67	    }
68	
69	    public static PlaceholderResolver getDefaultResolver() {
70	        return defaultResolver;
71	    }
72	
73	    public static PlaceholderResolver getResolver(String placeholderPrefix, String placeholderSuffix) {
74	        return new PlaceholderResolver(placeholderPrefix, placeholderSuffix);
75	    }
76	
77	    /**
78	     * Replace template string with special placeholder according to replace function.
79	     * @param content  template string with special placeholder
80	     * @param rule  placeholder replacement rule
81	     * @return new replaced string
82	     */
83	    public String resolveByRule(String content, Function<String, String> rule) {
84	        int start = content.indexOf(this.placeholderPrefix);
85	        if (start == -1) {
86	            return content;
87	        }
88	        StringBuilder result = new StringBuilder(content);
89	        while (start != -1) {
90	            int end = result.indexOf(this.placeholderSuffix, start);
91	            // get placeholder actual value (e.g. ${id}, get the value represent id)
92	            String placeholder = result.substring(start + this.placeholderPrefix.length(), end);
93	            // replace placeholder value
94	            String replaceContent = placeholder.trim().isEmpty() ? "" : rule.apply(placeholder);
95	            result.replace(start, end + this.placeholderSuffix.length(), replaceContent);
96	            start = result.indexOf(this.placeholderPrefix, start + replaceContent.length());
97	        }
98	        return result.toString();
99	    }
100	
101	    /**
102	     * Replace template string with special placeholder according to replace function.
103	     * @param file  template file with special placeholder
104	     * @param rule  placeholder replacement rule
105	     * @return new replaced string
106	     */
107	    public Path resolveByRule(Path file, Function<String, String> rule) {
108	        try {
109	            List<String> newContents = Files.readAllLines(file, StandardCharsets.UTF_8)
110	                    .stream()
111	                    .map(content -> resolveByRule(content, rule))
112	                    .collect(Collectors.toList());
113	            Path newPath = Paths.get(file.getParent().toString(), file.getFileName() + "$");
114	            Files.write(newPath, String.join(System.lineSeparator(), newContents).getBytes(StandardCharsets.UTF_8));
115	            return newPath;
116	        } catch (IOException e) {
117	            throw new RuntimeException(e);
118	        }
119	    }
120	
121	    /**
122	     * Replace template string with special placeholder according to properties file.
123	     * Key is the content of the placeholder <br/><br/>
124	     * e.g: content = product:${id}:detail:${did}<br/>
125	     *      valueMap = id -> 1; pid -> 2<br/>
126	     *      return: product:1:detail:2<br/>
127	     *
128	     * @param content template string with special placeholder
129	     * @param valueMap placeholder replacement map
130	     * @return new replaced string
131	     */
132	    public String resolveByMap(String content, final Map<String, Object> valueMap) {
133	        return resolveByRule(content, placeholderValue -> String.valueOf(valueMap.get(placeholderValue)));
134	    }
135	
136	    /**
137	     * Replace template string with special placeholder according to properties file.
138	     * Key is the content of the placeholder <br/><br/>
139	     * e.g: content = product:${id}:detail:${did}<br/>
140	     *      valueMap = id -> 1; pid -> 2<br/>
141	     *      return: product:1:detail:2<br/>
142	     *
143	     * @param file template string with special placeholder
144	     * @param valueMap placeholder replacement map
145	     * @return new replaced string
146	     */
147	    public Path resolveByMap(Path file, final Map<String, Object> valueMap) {
148	        return resolveByRule(file, placeholderValue -> String.valueOf(valueMap.get(placeholderValue)));
149	    }
150	}
