38	 * Test util for test container.
39	 */
40	public class TestUtils {
41	
42	    private static final ParameterProperty<Path> MODULE_DIRECTORY =
43	            new ParameterProperty<>("moduleDir", Paths::get);
44	
45	    /**
46	     * Searches for a resource file matching the given regex in the given directory. This method is
47	     * primarily intended to be used for the initialization of static {@link Path} fields for
48	     * resource file(i.e. jar, config file) that reside in the modules {@code target} directory.
49	     *
50	     * @param resourceNameRegex regex pattern to match against
51	     * @return Path pointing to the matching jar
52	     * @throws RuntimeException if none or multiple resource files could be found
53	     */
54	    public static Path getResource(final String resourceNameRegex) {
55	        // if the property is not set then we are most likely running in the IDE, where the working
56	        // directory is the
57	        // module of the test that is currently running, which is exactly what we want
58	        Path moduleDirectory = MODULE_DIRECTORY.get(Paths.get("").toAbsolutePath());
59	
60	        try (Stream<Path> dependencyResources = Files.walk(moduleDirectory)) {
61	            final List<Path> matchingResources =
62	                    dependencyResources
63	                            .filter(
64	                                    jar -> Pattern.compile(resourceNameRegex)
65	                                            .matcher(jar.toAbsolutePath().toString())
66	                                            .find())
67	                            .collect(Collectors.toList());
68	            switch (matchingResources.size()) {
69	                case 0:
70	                    throw new RuntimeException(
71	                            new FileNotFoundException(
72	                                    String.format(
73	                                            "No resource file could be found that matches the pattern %s. "
74	                                                    + "This could mean that the test module must be rebuilt via maven.",
75	                                            resourceNameRegex)));
76	                case 1:
77	                    return matchingResources.get(0);
78	                default:
79	                    throw new RuntimeException(
80	                            new IOException(
81	                                    String.format(
82	                                            "Multiple resource files were found matching the pattern %s. Matches=%s",
83	                                            resourceNameRegex, matchingResources)));
84	            }
85	        } catch (final IOException ioe) {
86	            throw new RuntimeException("Could not search for resource resource files.", ioe);
87	        }
88	    }
89	
90	    /**
91	     * A simple system properties value getter with default value when could not find the system property.
92	     * @param <V>
93	     */
94	    static class ParameterProperty<V> {
95	
96	        private final String propertyName;
97	        private final Function<String, V> converter;
98	
99	        public ParameterProperty(final String propertyName, final Function<String, V> converter) {
100	            this.propertyName = propertyName;
101	            this.converter = converter;
102	        }
103	
104	        /**
105	         * Retrieves the value of this property, or the given default if no value was set.
106	         *
107	         * @return the value of this property, or the given default if no value was set
108	         */
109	        public V get(final V defaultValue) {
110	            final String value = System.getProperty(propertyName);
111	            return value == null ? defaultValue : converter.apply(value);
112	        }
113	    }
114	
115	    @Test
116	    public void testReplaceholder() {
117	        String before = "today is ${date}, today weather is ${weather}";
118	        Map<String, Object> maps = new HashMap<>();
119	        maps.put("date", "2022.08.05");
120	        maps.put("weather", "rain");
121	        String after = PlaceholderResolver.getDefaultResolver().resolveByMap(before, maps);
122	        assertEquals(after, "today is 2022.08.05, today weather is rain");
123	    }
124	}
