++public abstract class FlinkContainerTestEnv extends TestLogger {
++
++    static final Logger JM_LOG = LoggerFactory.getLogger(JobMaster.class);
++    static final Logger TM_LOG = LoggerFactory.getLogger(TaskExecutor.class);
